"""undo, redo and history (docs/undo.md)."""

from binkeep import journal
from binkeep.bins import normalize
from binkeep.context import Context
from binkeep.errors import DataError, Refused

STOCK_OPS = ("receive", "issue", "move", "count", "fix")


def _broken(msg: str):
    return DataError("journal", msg)


def stacks(entries: list[dict]):
    """Reads the journal into (done, undone, dropped) lists of operation entries."""
    done, undone, dropped = [], [], []
    for e in entries:
        op = e["op"]
        if op in STOCK_OPS:
            dropped.extend(undone)
            undone.clear()
